package com.example.starter.web.dto;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.time.Instant;

/**
 * 窗口申请请求。所有时刻为 UTC，窗口必须为左闭右开。
 *
 * @param requestNo 申请编号（调用方保证唯一）
 * @param projectId 项目（研究组）标识
 * @param instrumentId 仪器标识
 * @param startAt 窗口开始时刻（UTC，包含）
 * @param endAt 窗口结束时刻（UTC，不包含）
 * @param durationMinutes 所需观测分钟数
 */
public record ApplyRequest(
        @NotBlank String requestNo,
        @NotBlank String projectId,
        @NotBlank String instrumentId,
        @NotNull Instant startAt,
        @NotNull Instant endAt,
        @Min(1) int durationMinutes) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 批准或撤销请求。
 *
 * @param projectId 撤销时必填，研究组只能撤销本项目的申请；批准可留空
 */
public record ActionRequest(
        @NotBlank String requestNo,
        String projectId) {
}

package com.example.starter.web.dto;

import com.example.starter.model.ObservationRequest;

import java.time.Instant;

/**
 * 申请视图：状态与（如有）接替来源。
 */
public record RequestView(
        String requestNo,
        String projectId,
        String instrumentId,
        Instant startAt,
        Instant endAt,
        int durationMinutes,
        String status,
        Instant requestedAt,
        String promotedFromRequestNo,
        Instant promotedAt) {

    public static RequestView from(ObservationRequest r, String promotedFromRequestNo) {
        return new RequestView(
                r.requestNo(), r.projectId(), r.instrumentId(),
                r.startAt(), r.endAt(), r.durationMinutes(),
                r.status().name(), r.requestedAt(),
                promotedFromRequestNo, r.promotedAt());
    }
}

package com.example.starter.web.dto;

import java.time.Instant;

/**
 * 仪器时间轴上的一个已分配区间。左闭右开。
 */
public record SlotView(
        String requestNo,
        String projectId,
        Instant startAt,
        Instant endAt,
        boolean fromPromotion,
        String promotedFromRequestNo) {
}

package com.example.starter.web.dto;

import java.util.List;

/**
 * 候补队列视图，按申请时间、申请编号升序排列。
 */
public record WaitlistView(String instrumentId, List<RequestView> waiting) {
}

package com.example.starter.web.dto;

import java.time.Instant;

/**
 * 一次候补接替事件的视图。
 */
public record PromotionView(
        String cancelledRequestNo,
        String promotedRequestNo,
        String instrumentId,
        Instant gapStartAt,
        Instant gapEndAt,
        Instant promotedAt) {
}

package com.example.starter.web.dto;

/**
 * 统一错误响应。
 */
public record ErrorResponse(String code, String message) {
}

