    /**
     * 申请列表，可按仪器/项目过滤。
     */
    List<RequestView> requests(String instrumentId, String projectId);

    /**
     * 某仪器候补顺序。
     */
    WaitlistView waitlist(String instrumentId);

    /**
     * 全部候补接替事件，按接替时刻升序。
     */
    List<PromotionView> promotions();

    /**
     * 撤销结果。
     *
     * @param cancelled 被撤销的申请
     * @param promoted 接替成功的候补；无接替为 null
     * @param gapStartAt 释放空档开始（UTC）；候补撤销无空档为 null
     * @param gapEndAt 释放空档结束（UTC）；候补撤销无空档为 null
     */
    record CancelOutcome(
            RequestView cancelled,
            RequestView promoted,
            Instant gapStartAt,
            Instant gapEndAt) {
    }
}

